INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '33a48e6c-64af-516b-ab70-fa01a2ad5572', 'cb3d016f-455d-5c62-90af-189b5b8cbdd7',
  'Heap (max-heap)?

Lựa chọn:
- A complete or nearly complete BST in which the key value of each node is greater than or equal to the key value in each of its descendants.
- A complete or nearly complete binary tree in which the key value of each node is greater than or equal to the key value in each of its descendants.
- A complete or nearly complete B-tree in which the key value of each node is greater than or equal to the key value in each of its descendants.
- All the other answers.', 4
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'acad7c2b-6c95-5a8f-8bde-8886edb0a491', 'cb3d016f-455d-5c62-90af-189b5b8cbdd7',
  'Heap in array?

Lựa chọn:
- For a node located at index $i$, its left child is at $2i + 1$, right child is at $2i + 2$.
- Given the size, $N$, of a complete heap, the location of the first leaf is $\lfloor N/2 \rfloor$.
- The parent of a node located at index $i$ is located at $\lfloor (i - 1)/2 \rfloor$.
- All of the other answers.', 5
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'c3d98693-65ca-547a-b904-e35c93e79512', 'cb3d016f-455d-5c62-90af-189b5b8cbdd7',
  '**Operations of heap?**

Lựa chọn:
- All the other answers.
- reheapUp/ reheapDown: repairs a "broken" heap by floating the last element up/the root down the tree until it is in its correct location in the heap.
- balanceLeft/ balanceRight: repairs a "broken" heap by borrow the left/right nodes of the "broken" subtrees until the tree is a heap.
- rotateUp/ rotateDown: repairs a "broken" heap by rotating up/down the subtrees until the tree is a heap.', 6
);

